"""Fixed-point-free rotation of S^3 and its SO(4) matrix."""
from __future__ import annotations
from math import cos, sin
from typing import List, Tuple

Vec4 = Tuple[float, float, float, float]

def rot4(x: Vec4) -> Vec4:
    x0, x1, x2, x3 = x
    return (-x1, x0, -x3, x2)

def sq_norm(x: Vec4) -> float:
    return sum(c * c for c in x)

def rot4_matrix() -> List[List[float]]:
    j = [[0.0, -1.0], [1.0, 0.0]]
    m = [[0.0] * 4 for _ in range(4)]
    for a in range(2):
        for b in range(2):
            m[a][b] = j[a][b]
            m[a + 2][b + 2] = j[a][b]
    return m

def demo() -> None:
    for x in [(1.0, 0.0, 0.0, 0.0), (cos(0.7), sin(0.7), 0.3, -0.3)]:
        rx = rot4(x); rrx = rot4(rx)
        print("x =", tuple(round(c, 3) for c in x))
        print("  isometry:", abs(sq_norm(rx) - sq_norm(x)) < 1e-12)
        print("  R^2 = -I:", all(abs(a + b) < 1e-12 for a, b in zip(rrx, x)))
        print("  fixed point on sphere:", all(abs(a - b) < 1e-12 for a, b in zip(rx, x)))

if __name__ == "__main__":
    demo()

"""Tesseract face counts and boundary Euler characteristics."""
from __future__ import annotations
from math import comb
from typing import List

def cube_face_counts(n: int) -> List[int]:
    """k-faces of the n-cube for k = 0..n."""
    return [comb(n, k) * 2 ** (n - k) for k in range(n + 1)]

def alternating_face_sum(n: int) -> int:
    return sum((-1) ** k * comb(n, k) * 2 ** (n - k) for k in range(n + 1))

def boundary_euler_char(n: int) -> int:
    """Euler characteristic of boundary S^(n-1): 1 - (-1)^n."""
    return 1 - (-1) ** n

def demo() -> None:
    names = {3: "cube surface (S^2)", 4: "tesseract boundary (S^3)"}
    for n in range(1, 6):
        counts = cube_face_counts(n)
        chi = sum((-1) ** k * c for k, c in enumerate(counts[:-1]))
        tag = names.get(n, "")
        print(f"n={n}: {counts}  full alt-sum={alternating_face_sum(n)}  "
              f"boundary chi={chi} (=1-(-1)^n={boundary_euler_char(n)}) {tag}")

if __name__ == "__main__":
    demo()

