function cube_invariants(n):
    counts <- [ C(n,k) * 2^(n-k)  for k in 0..n ]
    full     <- sum (-1)^k * counts[k]   over k in 0..n     # = 1
    boundary <- sum (-1)^k * counts[k]   over k in 0..n-1   # = 1 - (-1)^n
    return (counts, full, boundary)
